const days = { 1: 'الاثنين', 2: 'الثلاثاء', 3: 'الأربعاء', 4: 'الخميس', 5: 'الجمعة', 6: 'السبت', 7: 'الأحد' };
const today = days[DateTime.now().setZone('Africa/Cairo').weekday];
const norm = s => String(s || '').replace(/[أإآ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي').replace(/^ال/, '').trim();
const rows = $input.all().map(i => i.json);
const p = rows.find(r => norm(r.day).includes(norm(today)) || norm(today).includes(norm(r.day)));
if (!p) return [];
// المراجع: ينضف الكابشن ويمسك أي حاجة محتاجة قرارك
const fixed = [];
let caption = String(p.caption || '');
const before = caption;
caption = caption.replace(/📲?\s*(تواصل(\s*معنا)?(\s*فوراً)?\s*)?(عبر\s*)?(ال)?واتساب\s*:?\s*(\+?\d*x{3,}\w*|https?:\/\/wa\.me\/\d+)/gi, '📲 ابعتلنا على الواتساب — اللينك في البايو').replace(/\+?\d*x{4,}\w*/gi, '').replace(/https?:\/\/wa\.me\/\d+/g, 'اللينك في البايو');
if (caption !== before) fixed.push('شلت رقم وهمي وحطيت "اللينك في البايو"');
const issues = [];
if (caption.length < 40) issues.push('الكابشن قصير أو ناقص');
if (!p.hook) issues.push('مفيش جملة افتتاحية');
if (/\d[\d,.]*\s*(جنيه|ج\.م|EGP|LE)|خصم|عروض|عرض|مجان|ببلاش|ضمان|سعر|discount|%/i.test(caption)) issues.push('فيه سعر/عرض/مجاني/ضمان — اتأكد إنك موافق عليه');
if (/كواليس|فيلا في|من شغلنا|مشروع/i.test(p.topic + caption)) issues.push('بيتكلم عن شغل حقيقي — محتاج صور من مشروع فعلي');
const review = (issues.length ? '⚠️ ' + issues.join(' · ') : '✓ المراجع: البوست كامل') + (fixed.length ? ' · 🔧 ' + fixed.join(' · ') : '');
const msg = 'المنصة: ' + p.platform + ' · ' + p.format + '\n\nأول جملة: ' + p.hook + '\n\nالتصميم/اللقطة: ' + p.visual_idea + '\n\nالكابشن:\n' + caption + '\n\n' + p.hashtags;
return [{ json: { msg, topic: p.topic, review, row_id: p.id } }];

رتّب الليدز.jsCode:
const parts = $json.candidates?.[0]?.content?.parts || [];
const text = parts.map(p => p.text || '').join('');
const m = text.match(/\[[\s\S]*\]/);
let leads = [];
try { leads = JSON.parse(m ? m[0] : text); } catch (e) { leads = []; }
const now = DateTime.now().setZone('Africa/Cairo').toFormat('yyyy-MM-dd HH:mm');
const f = $('حدد المنطقة والنوع').first().json;
const seen = new Set();
const out = [];
for (const l of leads) {
  if (!l || !l.name) continue;
  const key = String(l.name).trim().toLowerCase();
  if (seen.has(key)) continue; seen.add(key);
  let phone = String(l.phone || '').replace(/[^0-9]/g, '');
  if (phone.startsWith('0')) phone = '2' + phone;
  out.push({ json: {
    name: l.name, category: l.category || f.segment, area: l.area || f.area,
    phone, email: l.email || '', website: l.website || '', why_fit: l.why_fit || '',
    whatsapp_msg: l.whatsapp_msg || '', email_subject: l.email_subject || '', email_body: l.email_body || '',
    status: 'new', found_at: now
  } });
}
if (!out.length) return [{ json: { _empty: true, raw: text.slice(0, 500) } }];
return out;

