// لو جاي من الفورم ناخد اختيارك، ولو من الروتين نلف على المناطق والأنواع يوم بيوم
const j = $json;
if (j.area && j.segment) return [{ json: { area: j.area, segment: j.segment, count: Number(j.count) || 15, source: 'form' } }];
const AREAS = ['التجمع الخامس', 'الشيخ زايد', '6 أكتوبر', 'مدينة نصر', 'المعادي', 'القاهرة الجديدة', 'مصر الجديدة'];
const SEGS = ['شركات تشطيب وديكور', 'مكاتب تصميم داخلي ومهندسين معماريين', 'مطورين عقاريين وكمباوندات', 'مقاولين كهرباء', 'فنادق وعيادات ومكاتب إدارية'];
const d = Math.floor(DateTime.now().setZone('Africa/Cairo').toSeconds() / 86400);
return [{ json: { area: AREAS[d % AREAS.length], segment: SEGS[Math.floor(d / AREAS.length) % SEGS.length], count: 12, source: 'routine' } }];

// المراجع: مفيش رسالة بتطلع لوحدها. كل عميل برقم بيبقى طلب موافقة في التطبيق، ولما توافق بيفتحلك واتساب بالرسالة تبعتها بإيدك
const leads = $('رتّب الليدز').all().map(i => i.json).filter(l => !l._empty);
const f = $('حدد المنطقة والنوع').first().json;
const day = DateTime.now().setZone('Africa/Cairo').toFormat('yyyy-MM-dd');
const base = { business: 'jaguar', agent: 'leads', ref_table: 'jaguar_leads', decided_at: '', day };
const out = [];
for (const l of leads) {
  if (!l.phone) continue;
  const issues = [];
  if (!/^20(1[0125]\d{8}|[2-9]\d{7,9})$/.test(l.phone)) issues.push('الرقم شكله مش مصري صحيح');
  if (!l.whatsapp_msg) issues.push('مفيش رسالة');
  if (/\d[\d,.]*\s*(جنيه|ج\.م|EGP|LE)|خصم|ببلاش|مجان|%/i.test(l.whatsapp_msg)) issues.push('الرسالة فيها سعر أو خصم — ممنوع من غير إذنك');
  if (l.name && !l.whatsapp_msg.includes(String(l.name).split(' ')[0])) issues.push('اسم الجهة مش مذكور في الرسالة');
  out.push({ json: { ...base, kind: 'approval', status: 'pending',
    title: 'رسالة لـ ' + l.name,
    body: (l.why_fit ? 'ليه اخترناه: ' + l.why_fit + '\n' : '') + (l.website ? 'الموقع: ' + l.website + '\n' : '') + '\nالرسالة:\n' + l.whatsapp_msg,
    link: 'https://wa.me/' + l.phone + '?text=' + encodeURIComponent(l.whatsapp_msg),
    review: issues.length ? '⚠️ ' + issues.join(' · ') : '✓ المراجع: الرقم والاسم سليمين ومفيش سعر أو خصم',
    ref_id: l.name } });
}
const noPhone = leads.filter(l => !l.phone);
let body = f.segment + ' — ' + f.area + '\nلقيت ' + leads.length + ' جهة، ' + out.length + ' منهم برقم (مستنيين موافقتك).';
if (noPhone.length) body += '\n\nمن غير رقم:\n' + noPhone.slice(0, 10).map(l => '• ' + l.name + (l.email ? ' — ' + l.email : '') + (l.website ? ' — ' + l.website : '')).join('\n');
if (!leads.length) body = 'مالقيتش نتايج لـ ' + f.segment + ' في ' + f.area + '.';
out.unshift({ json: { ...base, kind: 'report', status: 'done', title: 'صياد العملاء: ' + f.area, body, link: '', review: '', ref_id: '' } });
return out;

const today = DateTime.now().setZone('Africa/Cairo').toFormat('yyyy-MM-dd');
const all = $input.all().map(i => i.json).filter(r => r && r.id);
const rows = all.filter(r => r.day === today && r.agent !== 'summary');
const pending = all.filter(r => r.status === 'pending');
const by = {};
rows.forEach(r => { const k = r.agent || 'other'; by[k] = (by[k] || 0) + 1; });
const NAME = { content: 'كاتب المحتوى', leads: 'صياد العملاء', competitors: 'متابعة المنافسين', claude: 'Claude', tester: 'موظف التستنج' };
let body = 'اتعمل النهارده ' + rows.length + ' عملية.\n';
Object.keys(by).forEach(k => { body += '• ' + (NAME[k] || k) + ': ' + by[k] + '\n'; });
body += '\nوافقت على ' + rows.filter(r => r.status === 'approved').length + '، ورفضت ' + rows.filter(r => r.status === 'rejected').length + '.';
body += '\nمستني موافقتك: ' + pending.length + (pending.length ? ' (' + pending.slice(0, 5).map(r => r.title).join('، ') + ')' : '') + '.';
return [{ json: { kind: 'report', business: 'all', agent: 'summary', title: 'ملخص اليوم ' + today, body, link: '', status: 'done', review: '', ref_table: '', ref_id: '', decided_at: '', day: today } }];
